public static int writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || str.length() == 0) {
        return 0;
    }
    int size = 0;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.writeByte((byte) c);
