 * Computes the global separator list of the input graph.
 *
 * @param graph the input graph
 * @return the list of minimal separators of every edge in the graph
 */
public List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList(UndirectedGraph<V, E> graph) {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.edgeSet()) {
        List<Pair<Integer, Integer>> separator = computeMinimalSeparator(graph, e);
        globalSeparatorList.add(Pair.of(separator, e));
    }
    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new ArrayList<>();
    for (E e : graph.edges()) {
        List<Pair<Integer, Integer>> separator = computeMinimalSeparator(graph, e);
        separatorList.add(new Pair<>(separator, e));
    }
    return separatorList;
}

